const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);menu.setAttribute('aria-label',open?'Menü schließen':'Menü öffnen')});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus()}});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});let count=0;document.querySelectorAll('[data-category]').forEach(c=>{const show=b.dataset.filter==='Alle'||c.dataset.category===b.dataset.filter;c.hidden=!show;if(show)count++});document.querySelector('#filter-count').textContent=count+' Beckenarten im Überblick'}));const form=document.querySelector('#inquiry');if(form){const params=new URLSearchParams(location.search);const town=params.get('ort');if(town)document.querySelector('#place').value=town.slice(0,120);const pool=params.get('pool');const option=[...document.querySelector('#pool').options].find(x=>x.dataset.id===pool);if(option)option.selected=true;if(params.get('service')==='wartung')document.querySelector('#service').value='Pflege & Wartung';form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const msg=['Guten Tag,','', 'ich interessiere mich für '+data.get('service')+'.','Name: '+data.get('name'),'E-Mail: '+data.get('email'),'Projektort: '+data.get('place'),'Beckenart: '+data.get('pool'),'','Meine Wünsche:',data.get('message')].join('\n');document.querySelector('#mail-text').value=msg;document.querySelector('#mail-fallback').hidden=false;document.querySelector('#form-status').textContent='Ihre Nachricht ist vorbereitet. Bitte senden Sie diese in Ihrem E-Mail-Programm. Falls es sich nicht öffnet, kopieren Sie den Text und senden ihn an anfrage@srbauunternehmen.de.';location.href='mailto:anfrage@srbauunternehmen.de?subject='+encodeURIComponent('SR Pool – '+data.get('service')+' in '+data.get('place'))+'&body='+encodeURIComponent(msg)});document.querySelector('#copy-mail').addEventListener('click',async()=>{const text=document.querySelector('#mail-text');try{await navigator.clipboard.writeText(text.value);document.querySelector('#form-status').textContent='Nachricht kopiert. Bitte in Ihre E-Mail an anfrage@srbauunternehmen.de einfügen und versenden.'}catch{text.focus();text.select();document.querySelector('#form-status').textContent='Bitte kopieren Sie den markierten Nachrichtentext.'}})}